import{H as e,St as t,at as n,it as r,ot as i,st as a,tt as o,vt as s}from"./chunks/framework.dmHZ7NHG.js";var c=JSON.parse(`{"title":"Tests","description":"What uuidna's test suite verifies — crypto known-answer vectors, the no-Math purity guard, exact quantum simulation, encrypted streams, contract messaging, book audits, and that the Lean ℤ/9 facts recompute. Every test runs in the release gate before any publish.","frontmatter":{"title":"Tests","description":"What uuidna's test suite verifies — crypto known-answer vectors, the no-Math purity guard, exact quantum simulation, encrypted streams, contract messaging, book audits, and that the Lean ℤ/9 facts recompute. Every test runs in the release gate before any publish."},"headers":[],"relativePath":"docs/tests.md","filePath":"docs/tests.md"}`),l={name:`docs/tests.md`},u={id:`tests`,tabindex:`-1`};function d(e,c,l,d,f,p){let m=t(`Badge`);return s(),r(`div`,null,[o(`h1`,u,[c[0]||=i(`Tests `,-1),a(m,{type:`tip`,text:`the audit gate`}),c[1]||=i(),c[2]||=o(`a`,{class:`header-anchor`,href:`#tests`,"aria-label":`Permalink to “Tests”`},`​`,-1)]),c[3]||=n(`<blockquote><p>Nothing ships unless the whole suite passes — a failing test fails the publish, not production.</p></blockquote><p>The tests are one of the <strong>seven dimensions</strong> of the <a href="/guides#verify-every-theorem-yourself">release gate</a>: <code>npm run audit</code> runs build · Lean re-verification · provenance · <strong>tests</strong> · determinism, and only a clean run can publish. Run them yourself with <code>npm test</code>.</p><h2 id="what-each-suite-verifies" tabindex="-1">What each suite verifies <a class="header-anchor" href="#what-each-suite-verifies" aria-label="Permalink to “What each suite verifies”">​</a></h2><table tabindex="0"><thead><tr><th>suite</th><th>what it proves</th></tr></thead><tbody><tr><td><strong>kat</strong></td><td>The crypto primitives match the standards, byte for byte: SHA-256, HMAC-SHA256, PBKDF2, ChaCha20, Poly1305 and ChaCha20-Poly1305 AEAD against their <strong>RFC / NIST known-answer vectors</strong>. Not &quot;trust the code&quot; — reproduce the published test vectors.</td></tr><tr><td><strong>smoke</strong></td><td>The honest floor: the ℤ/9 vortex facts recompute (units, doubling orbit, digital roots, the involution&#39;s single fixed point), the order-invariant fold is order-invariant, and the <strong><code>Math.*</code> purity guard</strong> — a host <code>Math.*</code> call is hard-rejected from <code>src/</code>, because it is not a local theorem.</td></tr><tr><td><strong>quantum</strong></td><td>The state-vector simulator is <strong>exact</strong>: Gaussian-integer amplitudes over √(2ⁿ), no floats, no drift; Bell/GHZ distributions, per-qubit marginals (the no-signaling check), and the classical truth tables an H-free circuit computes.</td></tr><tr><td><strong>stream</strong></td><td>Encrypted uuid messaging round-trips both ways; onion layers peel outermost-first; a wrong key, a reordered key list, or a tampered chain <strong>throws</strong> (Poly1305 authentication); the ratchet breaks on a dropped or reordered link.</td></tr><tr><td><strong>contract</strong></td><td>Contract-keyed messaging: the domain <strong>is</strong> the contract&#39;s address; the public tag routes but the ciphertext does not leak the plaintext; a wrong contract is rejected; a <strong>license change invalidates old ciphertext</strong>.</td></tr><tr><td><strong>books</strong></td><td>The book audit: the content-address is the exact-copy fingerprint, chapters merkle-fold, the structural decode and ℤ/9 gravity recompute, and a translation binds source→translation directionally.</td></tr><tr><td><strong>pq · crypt-guard</strong></td><td>The post-quantum posture and the crypto guardrails — the honest bounds (Grover is a quadratic speedup, not a break) and the misuse checks.</td></tr></tbody></table><h2 id="the-discipline" tabindex="-1">The discipline <a class="header-anchor" href="#the-discipline" aria-label="Permalink to “The discipline”">​</a></h2><ul><li><strong>Known-answer, not self-attested.</strong> The crypto suites reproduce published vectors — the strongest honest check: the same input, the same standard output, no appeal to our own code.</li><li><strong>Purity is a test.</strong> <code>Math.*</code> in <code>src/</code> fails the suite — the library computes from local theorems, not a host&#39;s black-box math. Determinism (regenerating the ledger leaves the tree clean) is checked the same way.</li><li><strong>Failure is allowed.</strong> The suite <em>can</em> go red, and when it does the publish stops. That is the point — a green suite means something only because a red one blocks the release.</li></ul><p>The tests, the <a href="/trials">trials</a>, and the <a href="/theorems">theorems</a> are three readings of one discipline: recompute it yourself, or it does not count. Integrity, not truth.</p>`,7)])}var f=e(l,[[`render`,d]]);export{c as __pageData,f as default};